H.background();
// Heat transfer by conduction:  Q/t = k * A * (T_hot - T_cold) / L
// A wall/rod conducts heat from a hot side to a cold side. Convection and
// radiation also shown as labeled accents.
const w = H.W, h = H.H;
const kc = P.k;        // thermal conductivity W/(m*K)
const dT = P.dT;       // temperature difference across the slab (K)
const L = P.L;         // thickness of the slab (m)
const A = 1.0;         // area fixed at 1 m^2
const rate = (L > 1e-6) ? kc * A * dT / L : 0;  // conduction rate in watts
H.text("Heat conduction:  Q/t = k·A·ΔT / L", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("k = " + kc.toFixed(1) + " W/(m·K)    ΔT = " + dT.toFixed(0) + " K    L = " + L.toFixed(3) + " m    A = 1 m²", 24, 52, { color: H.colors.sub, size: 12 });
// Slab geometry
const sx = 220, sw = 260, sTop = 120, sBot = h - 90;
const sh = sBot - sTop;
// hot reservoir (left) and cold reservoir (right)
H.rect(sx - 80, sTop, 80, sh, { fill: H.hsl(10, 80, 45), radius: 4 });
H.rect(sx + sw, sTop, 80, sh, { fill: H.hsl(210, 80, 45), radius: 4 });
H.text("HOT", sx - 70, sTop - 8, { color: H.colors.warn, size: 13, weight: 700 });
H.text("COLD", sx + sw + 6, sTop - 8, { color: H.colors.accent, size: 13, weight: 700 });
// slab with a left-to-right temperature gradient (hot red -> cold blue)
const cols = 24;
for (let i = 0; i < cols; i++) {
  const f = i / (cols - 1);
  const hue = 10 + 200 * f;   // 10 (red) -> 210 (blue)
  H.rect(sx + (sw / cols) * i, sTop, sw / cols + 1, sh, { fill: H.hsl(hue, 75, 48) });
}
H.rect(sx, sTop, sw, sh, { stroke: H.colors.ink, width: 1.5 });
// thickness dimension marker
H.line(sx, sBot + 14, sx + sw, sBot + 14, { color: H.colors.sub, width: 1 });
H.text("L", sx + sw / 2 - 4, sBot + 30, { color: H.colors.sub, size: 12 });
// CONDUCTION: heat-flow arrows whose count/speed scale with the rate
const flow = (t * (0.4 + rate / 200)) % 1;
const nArrows = 3;
for (let i = 0; i < nArrows; i++) {
  const yy = sTop + sh * (0.3 + 0.2 * i);
  const xx = sx + ((flow + i / nArrows) % 1) * sw;
  H.arrow(xx, yy, xx + 26, yy, { color: H.colors.yellow, width: 3, head: 8 });
}
// CONVECTION: curling arrows rising off the hot side
const cv = (t * 0.8) % 1;
const cvy = sBot - cv * (sh - 10);
H.arrow(sx - 40, cvy, sx - 40, cvy - 20, { color: H.colors.good, width: 2.5, head: 7 });
H.text("convection", sx - 78, sTop + sh + 24, { color: H.colors.good, size: 11 });
// RADIATION: dashed wavy emission from the hot reservoir
const rphase = t * 4;
const rad = [];
for (let s = 0; s <= 30; s++) {
  const xx = sx - 80 - s * 1.6;
  const yy = sTop + sh * 0.5 + 6 * Math.sin(s * 0.6 - rphase);
  if (xx > 10) rad.push([xx, yy]);
}
H.path(rad, { color: H.colors.violet, width: 2 });
H.text("radiation", 24, sTop + sh * 0.5 - 10, { color: H.colors.violet, size: 11 });
H.text("conduction →", sx + 6, sTop + sh + 24, { color: H.colors.yellow, size: 11 });
// readout
H.text("Q/t = " + rate.toFixed(1) + " W", w - 170, 52, { color: H.colors.good, size: 15, weight: 700 });
H.text("(heat flow rate)", w - 170, 74, { color: H.colors.sub, size: 11 });
